const repositoryEvidence = {"commit":"2be80acd1ac68b01756c1acccad8010363755389","repository":"ALIYILD/DeepSynaps-Clinical-Intelligence-OS","reviewed":"2026-10-13","functions":[{"id":"DS01","title":"NERVE AI Orchestrator","status":"linked","detail":"Orchestration cycles exist; patient-specific clinical use is disabled for the NHS edition."},{"id":"DS02","title":"Deepy Clinical Assistant","status":"linked","detail":"Requires: Generative kill switch + LLM provider; ai_analysis consent for patient context."},{"id":"DS03","title":"Lead Doctor Agent","status":"linked","detail":"Runs as agent clinic.dr_ai through the governed agent runner; not embedded in workspace drafting."},{"id":"DS04","title":"Hermes Agent Network","status":"linked","detail":""},{"id":"DS05","title":"Clinical Intelligence Digest","status":"linked","detail":""},{"id":"DS06","title":"Patient 360° Intelligence","status":"partial","detail":"Workspace briefing combines DeepSynaps records only; no external clinical sources are connected."},{"id":"DS07","title":"25 Multimodal Analyzers","status":"linked","detail":""},{"id":"DS08","title":"qEEG Analyzer","status":"linked","detail":""},{"id":"DS09","title":"Neuroimaging Analyzers","status":"linked","detail":""},{"id":"DS10","title":"Cognitive Analyzer","status":"linked","detail":""},{"id":"DS11","title":"Biomarker & Laboratory Intelligence","status":"linked","detail":""},{"id":"DS12","title":"Genetic & Pharmacogenomic Context","status":"linked","detail":""},{"id":"DS13","title":"Voice Analyzer","status":"linked","detail":"Research-grade; its segment timestamps are synthetic and are never used by the workspace."},{"id":"DS14","title":"Behaviour, Video & Movement Analyzers","status":"linked","detail":""},{"id":"DS15","title":"Wearable Intelligence","status":"linked","detail":""},{"id":"DS16","title":"Sleep & Lifestyle Intelligence","status":"linked","detail":""},{"id":"DS17","title":"Medication Studio","status":"linked","detail":""},{"id":"DS18","title":"Mental Health Studio","status":"linked","detail":""},{"id":"DS19","title":"Rehabilitation Studio","status":"linked","detail":""},{"id":"DS20","title":"Neuromodulation Studio","status":"linked","detail":"Separately governed; not part of the NHS documentation edition."},{"id":"DS21","title":"Patient Timeline","status":"linked","detail":""},{"id":"DS22","title":"Brain, Bio, Mind & Body Twins","status":"linked","detail":"Research/context representations; excluded from NHS clinical use."},{"id":"DS23","title":"DeepTwin","status":"linked","detail":"Research simulation is excluded from the NHS edition (see E15)."},{"id":"DS24","title":"Patient Goals & Outcomes","status":"linked","detail":""},{"id":"DS25","title":"Evidence Intelligence","status":"ready","detail":""},{"id":"DS26","title":"NERVE Agent Memory","status":"partial","detail":"Clinician-controlled writing preferences only; no agent task memory. Never stores patient data."},{"id":"DS27","title":"Patient Application","status":"linked","detail":""},{"id":"DS28","title":"Clinical Quality & Verification Agents","status":"ready","detail":"Deterministic structural and source checks, not LLM agents."},{"id":"DS29","title":"Clinical OS Integration API","status":"enabled","detail":"Read-only FHIR partner API with signed events; no write-back, and API keys rather than OAuth/SMART backend services.; Requires: Patient data: DEEPSYNAPS_PARTNER_PHI_API_ENABLED, an admin-approved phi:read key under a data agreement, and the patient's third_party_app_sharing consent. Sandbox keys need none of these (synthetic patients only)."},{"id":"DS30","title":"Clinical Research Intelligence","status":"linked","detail":""},{"id":"DS31","title":"Patient Follow-up Intelligence","status":"ready","detail":""},{"id":"DS32","title":"Agent Evaluation & Controlled Improvement","status":"linked","detail":""},{"id":"C01","title":"Background noise reduction and speech-quality checking","status":"ready","detail":"Noise suppression and echo cancellation are the browser's own processing, shown as the browser reports them; there is no server-side denoising. The speech-quality check needs the deepsynaps_audio package and ai_analysis consent."},{"id":"C02","title":"Wearable or clip-on microphone integration","status":"ready","detail":"Any clip-on, USB or Bluetooth microphone the device exposes, with a level meter and a pause that keeps the audio if it disconnects; no vendor-specific pairing or device-side encryption (see C03)."},{"id":"C03","title":"Encrypted hardware audio capture and synchronisation","status":"external","detail":"Requires a hardware vendor and device-side encryption."},{"id":"C04","title":"Bluetooth / paired microphone and hands-free recording","status":"ready","detail":"Hands-free by dictation foot pedal (function keys) or headset button; no voice commands."},{"id":"C05","title":"Two-language interpretation transcript","status":"enabled","detail":"Machine-translated transcript draft; not a qualified interpreter.; Requires: Generative kill switch on + LLM provider + 'llm' in DEEPSYNAPS_CW_APPROVED_PROCESSORS"},{"id":"C06","title":"Spoken translation and on-screen translated text","status":"enabled","detail":"Spoken with on-device voices only, so patient text never goes to a cloud voice; a language without an installed voice is shown, not spoken. Machine translation, not a qualified interpreter.; Requires: Generative kill switch on + LLM provider + 'llm' in DEEPSYNAPS_CW_APPROVED_PROCESSORS"},{"id":"C07","title":"Generate clinical note drafts from interpreted conversations","status":"enabled","detail":"Requires: Generative kill switch on + LLM provider + 'llm' in DEEPSYNAPS_CW_APPROVED_PROCESSORS"},{"id":"C08","title":"Record consultations with explicit patient consent","status":"ready","detail":""},{"id":"C09","title":"Dictation without the patient present","status":"ready","detail":""},{"id":"C10","title":"Pause, resume, reset and delete recordings","status":"ready","detail":""},{"id":"C11","title":"Medical speech-to-text transcription","status":"enabled","detail":"General-purpose Whisper, on the server (faster-whisper) or OpenAI's outside the UK. Accuracy can be measured with the WER tool (NHS16) but no UK clinical benchmark has been run.; Requires: On-server: DEEPSYNAPS_CW_LOCAL_STT=1 + the local-stt extra (faster-whisper; audio stays on the server). Or external: OPENAI_API_KEY + WHISPER_EXTERNAL_EGRESS_ALLOWED + 'openai_whisper' in DEEPSYNAPS_CW_APPROVED_PROCESSORS (non-UK processor: DPIA approval)"},{"id":"C12","title":"Identify different speakers in a conversation","status":"enabled","detail":"AI suggests who said each line from what was said, not from voices (no acoustic diarisation); the clinician confirms every label before saving.; Requires: Generative kill switch on + LLM provider + 'llm' in DEEPSYNAPS_CW_APPROVED_PROCESSORS"},{"id":"C13","title":"Upload previously recorded audio","status":"ready","detail":""},{"id":"C14","title":"Full recording playback with timestamps","status":"ready","detail":""},{"id":"C15","title":"Section-specific audio replay","status":"ready","detail":""},{"id":"C16","title":"UK medical terminology and specialty vocabulary","status":"enabled","detail":"Built-in clinical lexicon plus clinic terms steer Whisper's spelling through its prompt; the effect on accuracy is unmeasured (compare WER with it on and off).; Requires: On-server: DEEPSYNAPS_CW_LOCAL_STT=1 + the local-stt extra (faster-whisper; audio stays on the server). Or external: OPENAI_API_KEY + WHISPER_EXTERNAL_EGRESS_ALLOWED + 'openai_whisper' in DEEPSYNAPS_CW_APPROVED_PROCESSORS (non-UK processor: DPIA approval)"},{"id":"C17","title":"Multilingual transcription","status":"enabled","detail":"Language hint or auto-detect via Whisper; per-language accuracy unmeasured.; Requires: On-server: DEEPSYNAPS_CW_LOCAL_STT=1 + the local-stt extra (faster-whisper; audio stays on the server). Or external: OPENAI_API_KEY + WHISPER_EXTERNAL_EGRESS_ALLOWED + 'openai_whisper' in DEEPSYNAPS_CW_APPROVED_PROCESSORS (non-UK processor: DPIA approval)"},{"id":"C18","title":"Live two-way interpretation","status":"enabled","detail":"Consecutive (turn by turn), a few seconds per turn, not simultaneous. Machine interpretation, not a qualified interpreter; not for consent.; Requires: On-server: DEEPSYNAPS_CW_LOCAL_STT=1 + the local-stt extra (faster-whisper; audio stays on the server). Or external: OPENAI_API_KEY + WHISPER_EXTERNAL_EGRESS_ALLOWED + 'openai_whisper' in DEEPSYNAPS_CW_APPROVED_PROCESSORS (non-UK processor: DPIA approval); Generative kill switch on + LLM provider + 'llm' in DEEPSYNAPS_CW_APPROVED_PROCESSORS"},{"id":"C19","title":"Record supported desktop and online meetings","status":"ready","detail":"Meetings running in a browser tab (Teams, Zoom or Meet on the web) in Chrome or Edge on a computer; desktop meeting apps and phone dial-ins are not captured. Everyone on the call must know."},{"id":"C20","title":"Offline audio recording and encrypted later sync","status":"ready","detail":"Browser-held key: clearing site data loses unsent recordings, and unsent items are deleted after 7 days. The server re-checks recording consent on upload. Web browser only; no native app."},{"id":"C21","title":"iOS, Android and desktop consultation capture","status":"ready","detail":"An installable web app (home screen) on iOS, Android and desktop with offline recording; no app-store apps, and a phone may stop recording if it locks the browser."},{"id":"C22","title":"Telehealth consultation capture","status":"ready","detail":"Captures a telehealth call running in a browser tab, under the patient's recording consent; no integration with a telehealth vendor's own recording."},{"id":"C23","title":"Multi-speaker and MDT meeting transcription","status":"enabled","detail":"Speakers are suggested from content against the attendee names the clinician enters; no acoustic diarisation.; Requires: On-server: DEEPSYNAPS_CW_LOCAL_STT=1 + the local-stt extra (faster-whisper; audio stays on the server). Or external: OPENAI_API_KEY + WHISPER_EXTERNAL_EGRESS_ALLOWED + 'openai_whisper' in DEEPSYNAPS_CW_APPROVED_PROCESSORS (non-UK processor: DPIA approval); Generative kill switch on + LLM provider + 'llm' in DEEPSYNAPS_CW_APPROVED_PROCESSORS"},{"id":"N01","title":"Organise notes into folders and workflows","status":"ready","detail":""},{"id":"N02","title":"Clinician/team documentation quality-assurance reports","status":"ready","detail":""},{"id":"N03","title":"Edit notes with natural-language AI commands","status":"enabled","detail":"Requires: Generative kill switch on + LLM provider + 'llm' in DEEPSYNAPS_CW_APPROVED_PROCESSORS"},{"id":"N04","title":"Remember clinician writing preferences with user controls","status":"ready","detail":""},{"id":"N05","title":"Generate structured SOAP notes","status":"ready","detail":""},{"id":"N06","title":"DAP, BIRP and specialty-specific note templates","status":"ready","detail":""},{"id":"N07","title":"Editable notes and version history","status":"ready","detail":"History is the audit trail plus the supersession chain, not a word-level diff."},{"id":"N08","title":"Clinician approval, signing and superseding amendments","status":"ready","detail":""},{"id":"N09","title":"Custom tone, length, structure and terminology","status":"enabled","detail":"Requires: Generative kill switch on + LLM provider + 'llm' in DEEPSYNAPS_CW_APPROVED_PROCESSORS"},{"id":"N10","title":"Verify note statements against source transcripts","status":"ready","detail":"Lexical match to transcript wording; does not establish clinical accuracy."},{"id":"N11","title":"AI note rewriting and summarisation","status":"enabled","detail":"Requires: Generative kill switch on + LLM provider + 'llm' in DEEPSYNAPS_CW_APPROVED_PROCESSORS"},{"id":"N12","title":"Referral letters","status":"ready","detail":""},{"id":"N13","title":"Discharge summaries","status":"ready","detail":""},{"id":"N14","title":"Patient-friendly consultation summaries","status":"ready","detail":"Structured template is always available; the AI plain-English draft needs the generative switch."},{"id":"N15","title":"Complex MDT and care reports","status":"ready","detail":""},{"id":"N16","title":"Care plans and support plans","status":"ready","detail":""},{"id":"N17","title":"Organisation-wide clinical document template library","status":"ready","detail":""},{"id":"N18","title":"Import scanned or handwritten clinical notes","status":"enabled","detail":"Read on the server, never sent out. Handwriting is read less reliably; low-confidence lines are flagged and the clinician corrects the text before saving it as a draft note.; Requires: Tesseract OCR with English data and poppler on the API server (the API image installs both)"},{"id":"N19","title":"Combine multiple documents into reviewed summaries","status":"enabled","detail":"Requires: Generative kill switch on + LLM provider + 'llm' in DEEPSYNAPS_CW_APPROVED_PROCESSORS"},{"id":"N20","title":"Export documents with audit and review records","status":"ready","detail":""},{"id":"F01","title":"Library of licensed, reusable clinical form templates","status":"ready","detail":""},{"id":"F02","title":"Upload multiple supporting files","status":"ready","detail":""},{"id":"F03","title":"Create organisation-specific form definitions","status":"ready","detail":""},{"id":"F04","title":"Reusable clinical assessment library","status":"ready","detail":""},{"id":"F05","title":"Detect fields in uploaded PDF forms","status":"ready","detail":"Fillable (AcroForm) PDFs only."},{"id":"F06","title":"Automatically populate PDF fields from authorised sources","status":"ready","detail":"Sources are the DeepSynaps patient record and recorded NHS Number; no EPR source."},{"id":"F07","title":"Show the original source behind every populated field","status":"ready","detail":""},{"id":"F08","title":"Form-template version management","status":"ready","detail":""},{"id":"F09","title":"OCR and handwriting extraction","status":"enabled","detail":"Text with per-line confidence; it does not fill PDF form fields from a scan. Handwriting accuracy is lower and every flagged line needs checking.; Requires: Tesseract OCR with English data and poppler on the API server (the API image installs both)"},{"id":"F10","title":"Mental health assessments and questionnaires","status":"ready","detail":""},{"id":"F11","title":"Community health and social care assessments","status":"ready","detail":"Barthel Index, Lawton IADL and MUST are scored from clinician-entered item scores with the working shown; the clinic uses its own authorised forms. Local clinical validation is still required (E09)."},{"id":"F12","title":"Deploy approved forms to patients","status":"ready","detail":""},{"id":"F13","title":"Clinician review, correction and approval before submission","status":"ready","detail":""},{"id":"T01","title":"AI web-chat intake assistant","status":"ready","detail":"A guided chat over a fixed, clinic-approved question flow from a single-use link, with red-flag emergency guidance; no free-text AI conversation and no clinical advice, by design."},{"id":"T02","title":"24/7 telephone intake handling","status":"external","detail":"Needs a telephony provider contract."},{"id":"T03","title":"Transfer calls to a human or clinical team","status":"external","detail":"Needs telephony."},{"id":"T04","title":"SMS summaries and follow-up communications","status":"enabled","detail":"Requires: Twilio credentials + DEEPSYNAPS_REMINDER_OUTBOX_ENABLED"},{"id":"T05","title":"Intake-to-CRM/case-management handoff","status":"ready","detail":"Hands over to DeepSynaps patient records and the work queue; no external CRM connector."},{"id":"T06","title":"Multilingual telephone conversations","status":"external","detail":"Needs telephony."},{"id":"T07","title":"Safeguarding concern flagging with human escalation","status":"ready","detail":"Clinician-raised only; nothing is flagged automatically."},{"id":"T08","title":"Today's appointments and patient linking","status":"ready","detail":""},{"id":"T09","title":"Automatically prepare pre-appointment briefings","status":"ready","detail":"Deterministic summary of stored records; no AI narrative."},{"id":"T10","title":"Extract follow-up actions from consultations","status":"enabled","detail":"Requires: Generative kill switch on + LLM provider + 'llm' in DEEPSYNAPS_CW_APPROVED_PROCESSORS"},{"id":"T11","title":"Clinician-approved task creation","status":"ready","detail":""},{"id":"T12","title":"Assign tasks to staff members","status":"ready","detail":""},{"id":"T13","title":"Shared team task management","status":"ready","detail":""},{"id":"T14","title":"Appointment reminders","status":"enabled","detail":"Requires: Twilio credentials + DEEPSYNAPS_REMINDER_OUTBOX_ENABLED"},{"id":"T15","title":"Create referral tasks and letter drafts","status":"ready","detail":""},{"id":"T16","title":"MDT handover workflows","status":"ready","detail":""},{"id":"T17","title":"Save reusable AI task routines","status":"enabled","detail":"Saved AI instructions are four-eyes approved and only fill the note editor as a suggestion; task routines create tasks and never call AI.; Requires: Generative kill switch on + LLM provider + 'llm' in DEEPSYNAPS_CW_APPROVED_PROCESSORS"},{"id":"T18","title":"Run approved routines on schedules or triggers","status":"enabled","detail":"Requires: An external scheduler calling run-due (no in-process scheduler)"},{"id":"T19","title":"Usage and administration workload analytics","status":"ready","detail":""},{"id":"T20","title":"AI telephone intake and structured call summaries","status":"external","detail":"Needs telephony."},{"id":"T21","title":"Configurable intake escalation and transfer policies","status":"external","detail":"Depends on telephone intake."},{"id":"E01","title":"Team preferences for trusted evidence sources","status":"ready","detail":"Applied as ordering in the workspace search; the federated service itself is unchanged."},{"id":"E02","title":"Pre-consultation EHR chart preparation","status":"ready","detail":"From DeepSynaps records; no external EHR."},{"id":"E03","title":"Clinical calculators with inspectable calculations","status":"ready","detail":""},{"id":"E04","title":"Reviewable clinical coding suggestions","status":"partial","detail":"ICD-10 lookup; SNOMED CT needs a UK licence and terminology server."},{"id":"E05","title":"Patient history, alerts and allergy information","status":"ready","detail":""},{"id":"E06","title":"Longitudinal patient timeline","status":"linked","detail":""},{"id":"E07","title":"Clinical literature and guideline search","status":"ready","detail":""},{"id":"E08","title":"Evidence summaries with citations and source links","status":"linked","detail":""},{"id":"E09","title":"Validated clinical calculators","status":"partial","detail":"Checked against published reference values; local clinical validation not done."},{"id":"E10","title":"SNOMED coding assistance","status":"external","detail":"Needs a SNOMED CT UK licence and terminology server."},{"id":"E11","title":"Uploaded clinical history and supporting documents","status":"ready","detail":""},{"id":"E12","title":"qEEG, MRI and cognitive assessment context","status":"linked","detail":""},{"id":"E13","title":"Biomarker, laboratory and wearable information","status":"linked","detail":""},{"id":"E14","title":"NERVE/Hermes agent coordination","status":"linked","detail":""},{"id":"E15","title":"Digital twin simulations","status":"excluded","detail":"Separate research and validation scope."},{"id":"E16","title":"Patient-specific diagnosis and treatment recommendations","status":"excluded","detail":"Excluded unless separately classified, validated and authorised."},{"id":"I01","title":"NHS Number and RiO patient identifier mapping","status":"ready","detail":"Local crosswalk with check-digit validation; not traced against PDS or RiO."},{"id":"I02","title":"Retrieve authorised demographics from RiO","status":"external","detail":"Needs Trust/vendor authorisation."},{"id":"I03","title":"EHR-embedded application and side-panel integration","status":"external","detail":"Needs an EPR vendor launch integration."},{"id":"I04","title":"Delete recordings by retention policy after confirmed submission","status":"enabled","detail":"Requires: A Trust-authorised EPR adapter (I07); until then nothing is confirmed, so nothing is deleted"},{"id":"I05","title":"Read appointments from the RiO diary","status":"external","detail":"Adapter fails closed until authorised."},{"id":"I06","title":"Read RiO allergies and clinical alerts","status":"external","detail":"Adapter fails closed until authorised."},{"id":"I07","title":"Submit clinician-approved notes to RiO","status":"external","detail":"Signed notes queue once in an idempotent outbox and stay 'awaiting authorisation'; delivery needs a Trust-authorised RiO adapter."},{"id":"I08","title":"EMIS patient context and approved integration","status":"external","detail":"Needs EMIS partner access."},{"id":"I09","title":"Versioned EPR contracts, sandbox and interoperability testing","status":"partial","detail":"Typed contract, fail-closed adapter, an idempotent retrying outbox and a partner-API sandbox (synthetic patients); no EPR vendor sandbox."},{"id":"I10","title":"Role-based permissions and consent enforcement","status":"ready","detail":""},{"id":"I11","title":"Audit history, security controls and retention policies","status":"ready","detail":"Purge runs when a clinic lead or an external scheduler calls it; there is no in-process scheduler."},{"id":"I12","title":"Clinical safety documentation and Trust assurance process","status":"approval","detail":"Accepted for testing by Dr Ali YILDIRIM, 13 Oct 2026 (SIGNOFF.md). Before real patients: the CSO-signed safety case and the Trust's assurance process."},{"id":"I13","title":"Autonomous prescribing or clinical orders","status":"excluded","detail":"Excluded."},{"id":"I14","title":"Unsupervised clinical risk triage","status":"excluded","detail":"Excluded."},{"id":"I15","title":"Self-training on identifiable NHS patient records","status":"excluded","detail":"Excluded without a separately authorised governance arrangement."},{"id":"NHS01","title":"FHIR R4 / approved interoperability interface","status":"partial","detail":"R4 DocumentReference with the NHS Number identifier and attachment hash, valid against base R4 with the official HL7 validator in CI. UK Core publishes no DocumentReference profile (draft only), so none is claimed; no EPR has accepted it."},{"id":"NHS02","title":"NHS identity, authentication and SSO","status":"external","detail":"No NHS CIS2 / SSO integration."},{"id":"NHS03","title":"NHS Number matching and identity reconciliation","status":"partial","detail":"Check-digit validation and in-clinic duplicate refusal; no PDS trace."},{"id":"NHS04","title":"Role- and organisation-based access controls","status":"ready","detail":""},{"id":"NHS05","title":"UK GDPR, DPIA and data processing agreements","status":"approval","detail":"Accepted for testing by Dr Ali YILDIRIM, 13 Oct 2026 (SIGNOFF.md). Before real patients: the DPO-approved DPIA and a signed agreement with each processor."},{"id":"NHS06","title":"DCB0129 manufacturer clinical safety evidence","status":"approval","detail":"Accepted for testing by Dr Ali YILDIRIM, 13 Oct 2026 (SIGNOFF.md). Before real patients: the hazard log with the CSO's severity, likelihood and residual-risk ratings."},{"id":"NHS07","title":"Support for local DCB0160 clinical safety assessment","status":"approval","detail":"Accepted for testing by Dr Ali YILDIRIM, 13 Oct 2026 (SIGNOFF.md). Before real patients: the deploying Trust's own DCB0160 assessment, signed by its CSO."},{"id":"NHS08","title":"DTAC and DSPT assurance evidence","status":"approval","detail":"Accepted for testing by Dr Ali YILDIRIM, 13 Oct 2026 (SIGNOFF.md). Before real patients: the organisation's DSPT submission and the completed DTAC pack."},{"id":"NHS09","title":"UK data residency and subprocessor controls","status":"partial","detail":"Fails closed: patient data reaches only processors the organisation lists as DPIA-approved. Speech-to-text and OCR can run on the server itself, so audio and documents stay where the server is; AI drafting still needs an external LLM processor, and the code cannot verify any processor's region."},{"id":"NHS10","title":"Secure audio storage, retention and deletion","status":"enabled","detail":"Key custody and rotation are a deployment responsibility.; Requires: DEEPSYNAPS_MEDIA_ENCRYPTION=1 + DEEPSYNAPS_MEDIA_ENC_KEY (S3 storage in production)"},{"id":"NHS11","title":"Human review and signing for generated documents","status":"ready","detail":""},{"id":"NHS12","title":"Immutable audit events and document versioning","status":"ready","detail":"Signed notes are immutable and versioned; the workspace audit trail is hash-chained, so edits are detectable but not prevented. Write-once storage is an infrastructure control."},{"id":"NHS13","title":"Accessible UI and mobile support","status":"partial","detail":"axe-core WCAG 2.2 A/AA rules run in CI on every Clinical Admin tab and the patient questionnaire (colour contrast is checked in a browser scan, clean in light and dark themes); a manual screen-reader and assistive-technology audit has not been done."},{"id":"NHS14","title":"Tenant-specific settings, template libraries and permissions","status":"ready","detail":""},{"id":"NHS15","title":"Monitoring, failure recovery, backups and rollback","status":"approval","detail":"Accepted for testing by Dr Ali YILDIRIM, 13 Oct 2026 (SIGNOFF.md). Before real patients: UK production hosting with a tested restore, monitoring, alerting and on-call."},{"id":"NHS16","title":"Clinical quality evaluation, bias analysis and speech-accuracy testing","status":"ready","detail":"The tools: word error rate overall and by label (accent, specialty) and PDQI-9 peer ratings of AI-assisted versus other notes. Each clinic must run them on its own data; no benchmark has been run yet."},{"id":"NHS17","title":"Local user training, support and incident management","status":"approval","detail":"Accepted for testing by Dr Ali YILDIRIM, 13 Oct 2026 (SIGNOFF.md). Before real patients: training, a support route and incident reporting agreed with the Trust."},{"id":"NHS18","title":"Per-feature intended-purpose and MHRA regulatory assessment","status":"approval","detail":"Accepted for testing by Dr Ali YILDIRIM, 13 Oct 2026 (SIGNOFF.md). Before real patients: a written intended-purpose and medical-device decision for each AI feature."}]};
